#include <bits/stdc++.h>
using namespace std;
int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);
    vector<pair<int,int>> ops;
    auto apply=[&](int x,int y){
        ops.push_back({x,y});
        vector<int> np;
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p=np;
    };
    for(int placed=0;placed<n;placed++){
        int target=placed+1;
        int pos=-1;
        for(int i=placed;i<n;i++) if(p[i]==target){pos=i;break;}
        if(pos==placed) continue;
        // Move p[pos] to p[placed]
        // Step 1: move to front (position 0) if not already
        if(pos>0){
            if(pos==1){
                // y=n-1, x must be >=1 and x+y<n => impossible
                // Use x=1,y=1: element at 1 goes to y+(1-x)=1+0=0? No: 1 is in middle range [1,n-2], maps to y+(i-x)=1+(1-1)=1. Not helpful.
                // x=1,y=n-2: element at 1, n-y=2, so 1<2 means in middle? x=1<=1<n-y=2: maps to y+(i-x)=n-2+0=n-2.
                // Then from n-2: y=n-(n-2)=2, x=1: 1+2<n needs n>3. Maps to 0.
                if(n>3){apply(1,n-2);apply(1,2);}
                else{apply(1,1);apply(1,1);}
            } else {
                int y=n-pos,x=1;
                apply(x,y);
            }
        }
        // Now target at position 0
        if(placed==0) continue;
        // Move from 0 to placed: x=1 sends pos 0 to n-1
        apply(1,1); // now at n-1
        // From n-1 to placed: y=1,x=n-1-placed; maps n-1 to 0... need to go to placed
        int y2=n-placed,x2=1;
        if(x2+y2<n) apply(x2,y2);
        else{apply(1,1);} // fallback
    }
    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
